/**
 * 3D art for the big feature icons: Microsoft Fluent Emoji, 3D style.
 * MIT license, https://github.com/microsoft/fluentui-emoji (WebP versions
 * from npm @lobehub/fluent-emoji-3d). Generated by tools/build_icons.py.
 *
 * The images are embedded, so they work offline and need no extra files.
 */

const ART = {
  build: 'data:image/webp;base64,',
  missed: 'data:image/webp;base64,',
  target: 'data:image/webp;base64,',
  timer: 'data:image/webp;base64,',
  search: 'data:image/webp;base64,',
  shield: 'data:image/webp;base64,',
  smart: 'data:image/webp;base64,',
  stats: 'data:image/webp;base64,',
  saved: 'data:image/webp;base64,',
  study: 'data:image/webp;base64,',
  trophy: 'data:image/webp;base64,',
  compass: 'data:image/webp;base64,',
  calendar: 'data:image/webp;base64,',
  bulb: 'data:image/webp;base64,',
  star: 'data:image/webp;base64,',
  medal: 'data:image/webp;base64,',
};

/** Names of the available art. */
export const ART_NAMES = Object.keys(ART);

/** A 3D picture (decorative: screen readers skip it). */
export function art(name, { size = 48 } = {}) {
  const img = document.createElement('img');
  img.className = `art art-${name}`;
  img.src = ART[name] || ART.compass;
  img.width = size;
  img.height = size;
  img.alt = '';
  img.decoding = 'async';
  img.draggable = false;
  return img;
}
